{"path": "/Users/charles/Desktop/folder/arc-dispatch/artifacts.py", "content": """"Per-task artifact directory: ~/.arc-dispatch/artifacts/{envelope_id}/

Replaces the single-blob session_store with structured per-task files.
Each envelope gets its own directory. Cross-task project context is kept
via a per-project symlink: artifacts/projects/{project_id}/latest -> {envelope_id}
"""
import time
from pathlib import Path

_BASE = Path.home() / ".arc-dispatch" / "artifacts"


def task_dir(envelope_id: str) -> Path:
    d = _BASE / envelope_id
    d.mkdir(parents=True, exist_ok=True)
    return d


def write(envelope_id: str, name: str, content) -> Path:
    p = task_dir(envelope_id) / name
    if isinstance(content, bytes):
        p.write_bytes(content)
    else:
        p.write_text(content, encoding="utf-8")
    return p


def read(envelope_id: str, name: str, default="") -> str:
    p = task_dir(envelope_id) / name
    try:
        return p.read_text(encoding="utf-8")
    except Exception:
        return default


def list_files(envelope_id: str, pattern="*") -> list:
    return sorted(task_dir(envelope_id).glob(pattern))


def link_project_latest(envelope_id: str, project_id: str) -> None:
    if not project_id:
        return
    proj_dir = _BASE / "projects" / _safe_name(project_id)
    proj_dir.mkdir(parents=True, exist_ok=True)
    link = proj_dir / "latest"
    target = _BASE / envelope_id
    try:
        if link.exists() or link.is_symlink():
            link.unlink()
        link.symlink_to(target)
    except Exception:
        pass


def get_project_context(project_id: str) -> str:
    link = _BASE / "projects" / _safe_name(project_id) / "latest"
    try:
        ctx_file = link / "context.md"
        if ctx_file.exists():
            return ctx_file.read_text(encoding="utf-8")
    except Exception:
        pass
    return ""


def save_project_context(envelope_id: str, project_id: str, context: str) -> None:
    write(envelope_id, "context.md", context[:4000])
    link_project_latest(envelope_id, project_id)


def save_executor_output(envelope_id: str, output: str) -> Path:
    """Save executor raw output to artifact directory."""
    return write(envelope_id, "executor_output.txt", output)


def save_git_diff(envelope_id: str, diff: str) -> Path:
    """Save git diff to artifact directory."""
    return write(envelope_id, "git_diff.patch", diff)


def save_validation_report(envelope_id: str, report: str) -> Path:
    """Save validator report to artifact directory."""
    return write(envelope_id, "validation_report.md", report)


def save_browser_report(envelope_id: str, report: str) -> Path:
    """Save browser harness report to artifact directory."""
    return write(envelope_id, "browser_report.md", report)


def get_task_summary(envelope_id: str) -> dict:
    """Return artifact summary for an envelope."""
    d = task_dir(envelope_id)
    files = list_files(envelope_id)
    return {
        "envelope_id": envelope_id,
        "artifact_dir": str(d),
        "file_count": len(files),
        "files": [f.name for f in files],
        "has_context": (d / "context.md").exists(),
        "has_executor_output": (d / "executor_output.txt").exists(),
        "has_git_diff": (d / "git_diff.patch").exists(),
        "has_validation": (d / "validation_report.md").exists(),
        "has_browser_report": (d / "browser_report.md").exists(),
    }


def _safe_name(s: str) -> str:
    return "".join(c if c.isalnum() or c in "-_._" else "_" for c in s)[:80]
