def verify_build(project_path: str, dry_run: bool = False) -> dict:
    """Run build verification."""
    if dry_run:
        return {"success": True, "output": "dry run", "error": None}

    pkg_json = Path(project_path) / "package.json"
    build_cmd = "npm run build"

    if pkg_json.is_file():
        try:
            pkg = json.loads(pkg_json.read_text())
            scripts = pkg.get("scripts", {})
            if "build" in scripts:
                build_cmd = "npm run build"
            elif "build:prod" in scripts:
                build_cmd = "npm run build:prod"
        except Exception:
            pass

    try:
        result = subprocess.run(
            build_cmd.split(),
            capture_output=True,
            text=True,
            cwd=project_path,
            timeout=120,
        )
        return {
            "success": result.returncode == 0,
            "output": result.stdout[-500:] if result.stdout else "",
            "error": result.stderr[-500:] if result.stderr else None,
        }
    except subprocess.TimeoutExpired:
        return {"success": False, "output": "", "error": "build timeout 120s"}
    except Exception as e:
        return {"success": False, "output": "", "error": str(e)}


def start_dev_server(project_path: str, port: int = 8080, dry_run: bool = False) -> dict:
    """Start dev server in background."""
    if dry_run:
        return {"success": True, "process": None, "url": f"http://localhost:{port}"}

    try:
        proc = subprocess.Popen(
            ["npm", "run", "dev", "--", "--port", str(port)],
            cwd=project_path,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
        )

        for i in range(30):
            time.sleep(1)
            try:
                import urllib.request
                urllib.request.urlopen(f"http://localhost:{port}", timeout=2)
                return {"success": True, "process": proc, "url": f"http://localhost:{port}"}
            except Exception:
                continue

        proc.kill()
        return {"success": False, "process": None, "error": "server timeout 30s"}
    except Exception as e:
        return {"success": False, "process": None, "error": str(e)}


def stop_dev_server(proc) -> None:
    """Stop dev server process."""
    if proc:
        try:
            proc.kill()
            proc.wait(timeout=5)
        except Exception:
            pass


def take_screenshot(url: str, output_path: str, dry_run: bool = False) -> dict:
    """Take screenshot of a URL using hermes browser."""
    if dry_run:
        return {"success": True, "path": output_path}

    hermes_cmd = os.environ.get("ARC_HERMES_CMD", "hermes")
    cmd = [
        hermes_cmd, "chat", "-q",
        f"打开 {url}，截图保存到 {output_path}，不要做其他操作。",
        "--toolsets", "browser",
    ]

    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            timeout=60,
            env={**os.environ, "HERMES_NO_BANNER": "1"},
        )

        if result.returncode == 0 and Path(output_path).is_file():
            return {"success": True, "path": output_path}
        return {"success": False, "error": result.stderr[:200]}
    except Exception as e:
        return {"success": False, "error": str(e)}


